function generateHourlyUsageReports():
    # Óránkénti aggregált usage riportok

    hourStart = now().truncate("hour") - 1.hour
    hourEnd = now().truncate("hour")

    # 1. Partner szintű aggregáció
    partnerUsage = DataUsage.aggregate([
        {
            "$match": {
                "reportedAt": {"$gte": hourStart, "$lt": hourEnd}
            }
        },
        {
            "$lookup": {
                "from": "profiles",
                "localField": "profileId",
                "foreignField": "profileId",
                "as": "profile"
            }
        },
        {
            "$group": {
                "_id": "$profile.partnerId",
                "totalBytes": {"$sum": "$totalBytes"},
                "sessionCount": {"$sum": 1},
                "uniqueProfiles": {"$addToSet": "$profileId"}
            }
        }
    ])

    for partner in partnerUsage:
        PartnerUsageReport.create({
            "reportId": generateUUID(),
            "partnerId": partner._id,
            "periodStart": hourStart,
            "periodEnd": hourEnd,
            "totalDataUsed": partner.totalBytes,
            "sessionCount": partner.sessionCount,
            "activeProfiles": len(partner.uniqueProfiles),
            "createdAt": now()
        })

    # 2. Country szintű aggregáció
    countryUsage = DataUsage.aggregate([
        {
            "$match": {
                "reportedAt": {"$gte": hourStart, "$lt": hourEnd}
            }
        },
        {
            "$group": {
                "_id": "$country",
                "totalBytes": {"$sum": "$totalBytes"},
                "sessionCount": {"$sum": 1}
            }
        }
    ])

    # 3. Network szintű aggregáció
    networkUsage = DataUsage.aggregate([
        {
            "$match": {
                "reportedAt": {"$gte": hourStart, "$lt": hourEnd}
            }
        },
        {
            "$group": {
                "_id": "$network",
                "totalBytes": {"$sum": "$totalBytes"},
                "avgSessionDuration": {"$avg": {"$subtract": ["$sessionEnd", "$sessionStart"]}}
            }
        }
    ])

    # 4. Analytics platform-ra push (pl. BigQuery, Snowflake)
    pushToAnalytics({
        "timestamp": hourEnd,
        "partnerUsage": partnerUsage,
        "countryUsage": countryUsage,
        "networkUsage": networkUsage
    })

