function detectFraud(event):
    # Real-time fraud detection multi-layered approach

    riskScore = 0
    fraudIndicators = []

    # 1. Velocity checks - szokatlan aktivitási minták
    if event.type == "profile.activation":
        # Ugyanazon IP-ről aktiválások száma rövid időn belül
        recentActivations = countRecentActivations(
            ipAddress=event.ipAddress,
            timeWindow=3600  # 1 óra
        )

        if recentActivations > 10:
            riskScore += 40
            fraudIndicators.append({
                "type": "HIGH_VELOCITY_ACTIVATIONS",
                "details": f"{recentActivations} activations from same IP in 1 hour"
            })

        # Ugyanazon eszközről (EID) aktiválások
        recentEIDActivations = countRecentActivations(
            eid=event.eid,
            timeWindow=86400  # 24 óra
        )

        if recentEIDActivations > 5:
            riskScore += 30
            fraudIndicators.append({
                "type": "DEVICE_ABUSE",
                "details": f"{recentEIDActivations} activations from same EID in 24h"
            })

    # 2. Geolocation anomaly detection
    if event.type == "data.usage":
        previousLocation = getLastKnownLocation(event.profileId)
        currentLocation = geolocateIP(event.ipAddress)

        if previousLocation and currentLocation:
            distance = calculateDistance(previousLocation, currentLocation)
            timeDiff = (now() - previousLocation.timestamp).seconds

            # Fizikailag lehetetlen utazási sebesség (pl. 1 óra alatt 5000 km)
            maxPossibleSpeed = 1000  # km/h (repülővel)
            calculatedSpeed = (distance / timeDiff) * 3600  # km/h

            if calculatedSpeed > maxPossibleSpeed:
                riskScore += 60
                fraudIndicators.append({
                    "type": "IMPOSSIBLE_TRAVEL",
                    "details": f"Travel speed {calculatedSpeed:.0f} km/h from {previousLocation.country} to {currentLocation.country}"
                })

    # 3. Usage pattern anomalies
    if event.type == "data.usage":
        profile = getProfile(event.profileId)

        # Szokatlanul magas data usage rövid idő alatt
        recentUsage = getUsageInTimeWindow(
            profileId=event.profileId,
            timeWindow=3600  # 1 óra
        )

        if recentUsage > (5 * 1024 * 1024 * 1024):  # 5GB 1 óra alatt
            riskScore += 35
            fraudIndicators.append({
                "type": "ABNORMAL_USAGE_SPIKE",
                "details": f"{formatBytes(recentUsage)} used in 1 hour"
            })

        # Éjszakai használat (helyi idő szerint)
        userLocalTime = convertToTimezone(now(), profile.timezone)

        if userLocalTime.hour >= 2 and userLocalTime.hour <= 5:
            # Éjszakai óriás letöltések gyanúsak lehetnek
            if recentUsage > (1 * 1024 * 1024 * 1024):  # 1GB
                riskScore += 20
                fraudIndicators.append({
                    "type": "SUSPICIOUS_NIGHT_USAGE",
                    "details": "Heavy usage during 2-5 AM local time"
                })

    # 4. Payment fraud detection
    if event.type == "order.created":
        # Email domain blacklist check
        emailDomain = event.customer.email.split('@')[1]

        if emailDomain in DISPOSABLE_EMAIL_DOMAINS:
            riskScore += 50
            fraudIndicators.append({
                "type": "DISPOSABLE_EMAIL",
                "details": f"Email domain {emailDomain} is known disposable provider"
            })

        # BIN (Bank Identification Number) analysis
        if event.paymentMethod == "credit_card":
            binData = lookupBIN(event.cardBin)

            # High-risk country mismatch
            if binData.country != event.billingCountry:
                riskScore += 25
                fraudIndicators.append({
                    "type": "COUNTRY_MISMATCH",
                    "details": f"Card issued in {binData.country}, billing in {event.billingCountry}"
                })

            # Prepaid card usage (higher fraud risk)
            if binData.cardType == "PREPAID":
                riskScore += 15
                fraudIndicators.append({
                    "type": "PREPAID_CARD",
                    "details": "Payment with prepaid card"
                })

        # Multiple failed payment attempts
        failedAttempts = countFailedPayments(
            email=event.customer.email,
            timeWindow=3600
        )

        if failedAttempts >= 3:
            riskScore += 45
            fraudIndicators.append({
                "type": "MULTIPLE_FAILED_PAYMENTS",
                "details": f"{failedAttempts} failed payment attempts in 1 hour"
            })

    # 5. Device fingerprinting
    if "deviceFingerprint" in event:
        # Device fingerprint változás ugyanazon user accountnál
        previousFingerprint = getLastDeviceFingerprint(event.userId)

        if previousFingerprint and previousFingerprint != event.deviceFingerprint:
            if (now() - previousFingerprint.timestamp).seconds < 3600:
                riskScore += 30
                fraudIndicators.append({
                    "type": "DEVICE_FINGERPRINT_CHANGE",
                    "details": "Device fingerprint changed within 1 hour"
                })

    # 6. Shared account detection
    if event.userId:
        uniqueIPs = countUniqueIPs(
            userId=event.userId,
            timeWindow=86400  # 24 óra
        )

        if uniqueIPs > 10:
            riskScore += 25
            fraudIndicators.append({
                "type": "SHARED_ACCOUNT_SUSPECTED",
                "details": f"Account accessed from {uniqueIPs} different IPs in 24h"
            })

    # 7. Partner-specific fraud patterns
    if event.partnerId:
        # Partner API abuse detection
        apiCallRate = getAPICallRate(
            partnerId=event.partnerId,
            timeWindow=60  # 1 perc
        )

        partnerRateLimit = getPartnerRateLimit(event.partnerId)

        if apiCallRate > partnerRateLimit * 1.5:  # 50% túllépés
            riskScore += 20
            fraudIndicators.append({
                "type": "API_ABUSE",
                "details": f"API call rate {apiCallRate}/min exceeds limit {partnerRateLimit}/min"
            })

        # Unusual order patterns
        recentOrders = getPartnerOrders(
            partnerId=event.partnerId,
            timeWindow=3600
        )

        avgOrdersPerHour = getAvgOrdersPerHour(event.partnerId, days=30)

        if len(recentOrders) > avgOrdersPerHour * 5:  # 5x átlag
            riskScore += 35
            fraudIndicators.append({
                "type": "UNUSUAL_ORDER_VOLUME",
                "details": f"{len(recentOrders)} orders vs {avgOrdersPerHour:.0f} average"
            })

    # 8. Machine learning model prediction
    if ML_FRAUD_MODEL_ENABLED:
        mlFeatures = extractFraudFeatures(event)
        mlPrediction = fraudMLModel.predict(mlFeatures)

        if mlPrediction.fraudProbability > 0.7:
            riskScore += mlPrediction.fraudProbability * 50
            fraudIndicators.append({
                "type": "ML_HIGH_RISK",
                "details": f"ML model fraud probability: {mlPrediction.fraudProbability:.2%}"
            })

    # 9. Risk score normalizálás és kategorizálás
    riskScore = min(riskScore, 100)  # Max 100

    if riskScore >= 80:
        riskLevel = "CRITICAL"
        action = "BLOCK"
    elif riskScore >= 60:
        riskLevel = "HIGH"
        action = "MANUAL_REVIEW"
    elif riskScore >= 40:
        riskLevel = "MEDIUM"
        action = "FLAG"
    elif riskScore >= 20:
        riskLevel = "LOW"
        action = "MONITOR"
    else:
        riskLevel = "MINIMAL"
        action = "ALLOW"

    # 10. Fraud event rögzítés
    fraudEvent = FraudEvent.create({
        "fraudEventId": generateUUID(),
        "eventType": event.type,
        "entityType": event.entityType,  # order, profile, user, partner
        "entityId": event.entityId,
        "riskScore": riskScore,
        "riskLevel": riskLevel,
        "recommendedAction": action,
        "indicators": fraudIndicators,
        "eventData": event,
        "reviewedBy": null,
        "reviewedAt": null,
        "finalDecision": null,
        "createdAt": now()
    })

    # 11. Automatikus action végrehajtás
    if action == "BLOCK":
        executeBlockAction(event)

        # Alert küldés fraud team-nek
        sendFraudAlert("CRITICAL", fraudEvent)

    elif action == "MANUAL_REVIEW":
        # Queue-ba tesszük manual review-ra
        FraudReviewQueue.add(fraudEvent)

        # Alert küldés
        sendFraudAlert("HIGH", fraudEvent)

        # Temporary hold a tranzakción
        if event.type == "order.created":
            Order.update(event.orderId, {"status": "ON_HOLD", "holdReason": "FRAUD_REVIEW"})

    elif action == "FLAG":
        # Csak logging és monitoring
        logFraudFlag(fraudEvent)

    # 12. Real-time dashboard update
    updateFraudDashboard(riskLevel, fraudEvent)

    return {
        "riskScore": riskScore,
        "riskLevel": riskLevel,
        "action": action,
        "indicators": fraudIndicators
    }

end function

function executeBlockAction(event):
    # Blocking logic különböző event típusokhoz

    if event.type == "order.created":
        # Order cancellation
        Order.update(event.orderId, {
            "status": "CANCELLED",
            "cancellationReason": "FRAUD_DETECTED"
        })

        # Payment refund (ha már megtörtént)
        if event.paymentStatus == "PAID":
            initiateRefund(event.orderId, "FRAUD_DETECTED")

    elif event.type == "profile.activation":
        # Profil deaktiválás
        Profile.update(event.profileId, {
            "state": "UNAVAILABLE",
            "suspensionReason": "FRAUD_SUSPECTED"
        })

        # SM-DP+ értesítés a profil disable-ről
        smdpClient.disableProfile(event.iccid)

    elif event.type == "data.usage":
        # Session terminálás
        terminatePDNSession(event.sessionId)

        # Profil suspend
        Profile.update(event.profileId, {
            "state": "UNAVAILABLE",
            "suspensionReason": "FRAUDULENT_USAGE"
        })

    # User account suspend (ha user szintű fraud)
    if event.userId:
        User.update(event.userId, {
            "accountStatus": "SUSPENDED",
            "suspensionReason": "FRAUD_DETECTED",
            "suspendedAt": now()
        })

    # Partner account suspend (ha partner szintű fraud)
    if event.partnerId:
        Partner.update(event.partnerId, {
            "isActive": false,
            "suspensionReason": "FRAUD_DETECTED",
            "suspendedAt": now()
        })

        # API access revoke
        revokeAPIAccess(event.partnerId)

