### Rate Limiting Algorithm (Token Bucket)

```
function checkRateLimit(partnerId, endpoint):
    # Token bucket algoritmus rate limiting-hez

    # 1. Partner rate limit konfiguráció lekérdezés
    rateLimitConfig = getPartnerRateLimit(partnerId, endpoint)

    bucketCapacity = rateLimitConfig.requestsPerMinute
    refillRate = bucketCapacity / 60.0  # tokens per second

    # 2. Redis key a bucket tároláshoz
    bucketKey = f"ratelimit:{partnerId}:{endpoint}"

    # 3. Current bucket state lekérdezés
    bucketState = redis.get(bucketKey)

    if not bucketState:
        # Új bucket inicializálás
        bucketState = {
            "tokens": bucketCapacity,
            "lastRefill": now().timestamp()
        }
    else:
        bucketState = json.loads(bucketState)

    # 4. Tokens refill időalapú
    currentTime = now().timestamp()
    timePassed = currentTime - bucketState["lastRefill"]

    # Refill amount számítás
    refillAmount = timePassed * refillRate
    bucketState["tokens"] = min(
        bucketCapacity,
        bucketState["tokens"] + refillAmount
    )
    bucketState["lastRefill"] = currentTime

    # 5. Token consumption check
    if bucketState["tokens"] >= 1.0:
        # Van elég token - request engedélyezve
        bucketState["tokens"] -= 1.0

        # State mentés Redisbe
        redis.setex(
            bucketKey,
            120,  # TTL 2 perc
            json.dumps(bucketState)
        )

        return {
            "allowed": true,
            "remaining": int(bucketState["tokens"]),
            "limit": bucketCapacity,
            "resetAt": currentTime + ((bucketCapacity - bucketState["tokens"]) / refillRate)
        }
    else:
        # Nincs elég token - rate limit exceeded
        retryAfter = (1.0 - bucketState["tokens"]) / refillRate

        # Rate limit túllépés rögzítés
        logRateLimitExceeded(partnerId, endpoint)

        # Increment violation counter
        violationKey = f"ratelimit:violations:{partnerId}:{endpoint}:{currentTime // 3600}"
        violations = redis.incr(violationKey)
        redis.expire(violationKey, 3600)

        # Ha túl sok violation, temporary ban
        if violations > 100:
            banPartnerTemporarily(partnerId, duration=3600)  # 1 óra ban

        return {
            "allowed": false,
            "remaining": 0,
            "limit": bucketCapacity,
            "retryAfter": int(retryAfter),
            "resetAt": currentTime + retryAfter
        }

