### Cache Invalidation Strategy

```
function invalidateCacheOnUpdate(entity, entityId, operation):
    # Smart cache invalidation különböző entity típusokhoz

    keysToInvalidate = []

    if entity == "Profile":
        profile = getProfile(entityId)

        # Direkt profile cache
        keysToInvalidate.append(f"profile:{entityId}")
        keysToInvalidate.append(f"profile:iccid:{profile.iccid}")

        # User profiles list cache
        if profile.userId:
            keysToInvalidate.append(f"user:profiles:{profile.userId}")

        # Partner profiles list cache
        if profile.partnerId:
            keysToInvalidate.append(f"partner:profiles:{profile.partnerId}")

        # Profile state cache
        keysToInvalidate.append(f"profile:state:{profile.iccid}")

        # Usage cache
        keysToInvalidate.append(f"usage:{entityId}")

    elif entity == "Order":
        order = getOrder(entityId)

        # Order cache
        keysToInvalidate.append(f"order:{entityId}")

        # User orders cache
        if order.userId:
            keysToInvalidate.append(f"user:orders:{order.userId}")

        # Partner orders cache
        if order.partnerId:
            keysToInvalidate.append(f"partner:orders:{order.partnerId}")

    elif entity == "Plan":
        plan = getPlan(entityId)

        # Plan cache
        keysToInvalidate.append(f"plan:{entityId}")
        keysToInvalidate.append(f"plan:slug:{plan.planCode}")

        # Catalog cache (country specific)
        if plan.countryCode:
            keysToInvalidate.append(f"plan:catalog:{plan.countryCode}")

        if plan.regionCode:
            keysToInvalidate.append(f"plan:catalog:{plan.regionCode}")

        # Global catalog
        keysToInvalidate.append(f"plan:catalog:all")

    elif entity == "Partner":
        # Partner data cache
        keysToInvalidate.append(f"partner:{entityId}")

        # Partner balance cache
        keysToInvalidate.append(f"balance:partner:{entityId}")

        # API key cache
        partner = getPartner(entityId)
        keysToInvalidate.append(f"partner:apikey:{hashAPIKey(partner.apiKey)}")

    # Batch delete from Redis
    if keysToInvalidate:
        redis.delete(*keysToInvalidate)

    # Cache invalidation event publish (for distributed cache)
    publishCacheInvalidationEvent({
        "entity": entity,
        "entityId": entityId,
        "operation": operation,
        "keys": keysToInvalidate,
        "timestamp": now()
    })

end function
