**Database partitioning strategy**:

```sql
-- Usage data time-based partitioning
CREATE TABLE data_usage (
    usage_id UUID NOT NULL,
    iccid VARCHAR(20) NOT NULL,
    profile_id UUID NOT NULL,
    session_start TIMESTAMP NOT NULL,
    session_end TIMESTAMP,
    bytes_uploaded BIGINT NOT NULL,
    bytes_downloaded BIGINT NOT NULL,
    total_bytes BIGINT NOT NULL,
    rat_type VARCHAR(10),
    country VARCHAR(2),
    network VARCHAR(100),
    created_at TIMESTAMP NOT NULL DEFAULT NOW()
) PARTITION BY RANGE (created_at);

-- Monthly partitions
CREATE TABLE data_usage_2026_01 PARTITION OF data_usage
    FOR VALUES FROM ('2026-01-01') TO ('2026-02-01');

CREATE TABLE data_usage_2026_02 PARTITION OF data_usage
    FOR VALUES FROM ('2026-02-01') TO ('2026-03-01');

-- Automated partition management with pg_partman extension
SELECT partman.create_parent(
    'public.data_usage',
    'created_at',
    'native',
    'monthly',
    p_premake := 3,
    p_start_partition := '2026-01-01'
);

-- Transaction history partitioning by partner
CREATE TABLE transactions (
    transaction_id UUID NOT NULL,
    partner_id UUID NOT NULL,
    amount DECIMAL(10,2) NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT NOW()
) PARTITION BY HASH (partner_id);

-- 16 hash partitions for balanced distribution
CREATE TABLE transactions_p0 PARTITION OF transactions
    FOR VALUES WITH (MODULUS 16, REMAINDER 0);
CREATE TABLE transactions_p1 PARTITION OF transactions
    FOR VALUES WITH (MODULUS 16, REMAINDER 1);
-- ... up to p15
```

