# SM-DP+ ES2+ interfész implementáció (Python példa)

class ES2PlusInterface:
    """
    ES2+ interfész az SM-DP+ és operátor backend között
    GSMA SGP.22 v3.1 szerint
    """

    def __init__(self, operator_id, sm_dp_url, certificates):
        self.operator_id = operator_id
        self.sm_dp_url = sm_dp_url
        self.client_cert = certificates['client_cert']
        self.client_key = certificates['client_key']
        self.ca_cert = certificates['ca_cert']

    def download_order(self, order_data):
        """
        ES2+.DownloadOrder - Profil megrendelés SM-DP+-ra
        """
        request = {
            "header": {
                "functionRequesterIdentifier": self.operator_id,
                "functionCallIdentifier": generate_uuid()
            },
            "iccid": order_data['iccid'],
            "eid": order_data.get('eid'),  # Opcionális
            "profileType": order_data['profile_type'],
            "mno-id": self.operator_id,
            "subscriptionAddress": {
                "imsi": order_data['imsi'],
                "msisdn": order_data.get('msisdn')
            },
            "operatorID": {
                "mcc": order_data['mcc'],
                "mnc": order_data['mnc']
            },
            "pol2": order_data.get('policy_rules'),  # Profile Policy Rules
            "smdpAllocated": True
        }

        # Mutual TLS connection
        session = requests.Session()
        session.cert = (self.client_cert, self.client_key)
        session.verify = self.ca_cert

        response = session.post(
            f"{self.sm_dp_url}/gsma/rsp2/es2plus/downloadOrder",
            json=request,
            headers={"Content-Type": "application/json"},
            timeout=30
        )

        if response.status_code == 200:
            result = response.json()
            return {
                "success": True,
                "iccid": result['iccid'],
                "matchingId": result.get('matchingId'),
                "smdpAddress": result['smdpAddress'],
                "confirmationCodeRequired": result.get('confirmationCodeRequired', False),
                "confirmationCode": result.get('confirmationCode')
            }
        else:
            raise ES2PlusError(f"DownloadOrder failed: {response.text}")

    def confirm_order(self, iccid, release_flag=True):
        """
        ES2+.ConfirmOrder - Megrendelés megerősítés
        """
        request = {
            "header": {
                "functionRequesterIdentifier": self.operator_id,
                "functionCallIdentifier": generate_uuid()
            },
            "iccid": iccid,
            "releaseFlag": release_flag,
            "matchingId": None  # SM-DP+ fills this
        }

        session = requests.Session()
        session.cert = (self.client_cert, self.client_key)
        session.verify = self.ca_cert

        response = session.post(
            f"{self.sm_dp_url}/gsma/rsp2/es2plus/confirmOrder",
            json=request,
            timeout=30
        )

        if response.status_code == 200:
            return {"success": True, "released": release_flag}
        else:
            raise ES2PlusError(f"ConfirmOrder failed: {response.text}")

    def cancel_order(self, iccid, reason):
        """
        ES2+.CancelOrder - Megrendelés törlés
        """
        request = {
            "header": {
                "functionRequesterIdentifier": self.operator_id,
                "functionCallIdentifier": generate_uuid()
            },
            "iccid": iccid,
            "finalProfileStatusIndicator": "Cancelled",
            "cancellationReason": reason
        }

        session = requests.Session()
        session.cert = (self.client_cert, self.client_key)
        session.verify = self.ca_cert

        response = session.post(
            f"{self.sm_dp_url}/gsma/rsp2/es2plus/cancelOrder",
            json=request,
            timeout=30
        )

        return response.status_code == 200

    def handle_notification(self, notification_data):
        """
        ES2+.HandleNotification - SM-DP+-ról érkező értesítések
        """
        event_type = notification_data.get('profileManagementOperation')
        iccid = notification_data.get('iccid')
        eid = notification_data.get('eid')

        if event_type == "install":
            # Profil telepítve az eszközre
            self._handle_profile_installed(iccid, eid, notification_data)
        elif event_type == "enable":
            # Profil engedélyezve
            self._handle_profile_enabled(iccid, eid)
        elif event_type == "disable":
            # Profil letiltva
            self._handle_profile_disabled(iccid, eid)
        elif event_type == "delete":
            # Profil törölve
            self._handle_profile_deleted(iccid, eid)

        return {"processedSuccessfully": True}

    def _handle_profile_installed(self, iccid, eid, data):
        """Profil installed event kezelés"""
        # Database update
        Profile.objects.filter(iccid=iccid).update(
            state='INSTALLED',
            eid=eid,
            installed_at=datetime.now()
        )

        # Trigger webhook
        trigger_webhook('profile.installed', {
            'iccid': iccid,
            'eid': eid
        })

    def _handle_profile_enabled(self, iccid, eid):
        """Profil enabled event kezelés"""
        profile = Profile.objects.get(iccid=iccid)
        profile.state = 'ENABLED'
        profile.activated_at = datetime.now()

        # Ha first_usage trigger, validity start beállítás
        if profile.plan.validity_trigger == 'first_usage':
            profile.expires_at = datetime.now() + timedelta(days=profile.plan.validity_days)

        profile.save()

        # HLR/HSS provisioning - IMSI aktiválás
        self._provision_hlr(profile.imsi, enable=True)

        # Webhook trigger
        trigger_webhook('profile.activated', {
            'iccid': iccid,
            'eid': eid,
            'imsi': profile.imsi
        })
